using LPLK_Parachute;
using LPLK_BombWires;
using LPLK_Maps;
using LPLK_Whitelist;

int checks=0;
void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
void Reject(Action action,string message){bool rejected=false;try{action();}catch(InvalidDataException){rejected=true;}Check(rejected,message);}
var fall=new ParachuteSettings();
Check(FallPolicy.Brake(-900,fall)==-885,"Preserve v5 gradual braking instead of instant cap.");
Check(FallPolicy.Brake(-20,fall)==-85,"Preserve v5 linear terminal speed.");
Check(FallPolicy.Brake(200,fall)==200,"Jump velocity must remain unchanged.");
Check(FallPolicy.Brake(-91,fall)==-76,"Preserve exact v5 tick step before terminal speed.");
Check(FallPolicy.Brake(-900,fall with{BrakePerTick=0})==-85,"Preserve v5 immediate mode when decrease is zero.");
Check(FallPolicy.Brake(-20,fall with{Linear=false})==-5,"Preserve v5 non-linear mode.");
Check(FallPolicy.ReleaseGravity(0.1f,0.4f)==0.4f,"Restore original custom gravity instead of forcing 1.");
Check(FallPolicy.ReleaseGravity(0.3f,1)==0.3f,"Do not overwrite another plugin's later gravity change.");
Reject(()=>ParachuteSettings.Validate(fall with{FallSpeed=float.NaN}),"Non-finite settings rejected.");
var wire=new WireRound();wire.Begin(100);int first=wire.Generation;
Check(!wire.Choose(200,first,2),"Only planter can choose wire.");
Check(wire.Choose(100,first,2),"Planter choice accepted.");wire.Plant(0);
Check(!wire.Choose(100,first,1),"Wire cannot change after planting.");
Check(wire.Cut(first,2)==true,"Correct wire defuses.");
Check(wire.Cut(first,1) is null,"Bomb can only resolve once.");
wire.Begin(100);wire.Plant(1);
Check(wire.Cut(first,1) is null,"Previous-round menu cannot affect new bomb.");
Check(wire.Cut(wire.Generation,2)==false,"Wrong wire explodes.");wire.Reset();
Check(wire.Cut(wire.Generation,1) is null,"No planted bomb cannot resolve.");
List<MapEntry> maps=[new(){Id="de_dust2",Name="de_dust2"},new(){Id="123",Name="custom_map",MinPlayers=4,MaxPlayers=8},new(){Id="456",Name="sound_assets",IsMap=false},new(){Id="789",Name="disabled",Enabled=false}];
MapPolicy.Validate(maps);
Check(MapPolicy.Eligible(maps,"de_dust2","",0,[],3).Single().Id=="123","Empty-server fallback must ignore population, exclude current/assets/disabled.");
Check(MapPolicy.Eligible(maps,"de_dust2","",2,[],3).Count==0,"Population restrictions respected.");
Check(MapPolicy.Eligible(maps,"custom_map","123",5,[],3).All(m=>m.Id!="123"),"Workshop identity excludes current map.");
Check(MapPolicy.Eligible(maps,"de_dust2","",5,["123"],3).Count==0,"Cooldown excludes nominations.");
Check(MapPolicy.Eligible(maps,"de_dust2","",5,["123"],3,true).Single().Id=="123","Cooldown relaxation only retains valid maps.");
Check(!MapPolicy.Matches(maps[1],"custom_map","999"),"Wrong workshop ID cannot count as success even with matching filename.");
Check(MapPolicy.RequiredRtv(3,60)==2,"RTV must round up.");
Check(MapPolicy.Leaders(maps.Take(2).ToList(),[],new HashSet<string>{"123"}).Single().Id=="123","No-vote tie must favor nomination.");
Reject(()=>MapPolicy.Validate([new(){Id="de_dust2;quit",Name="bad"}]),"Map command injection rejected.");
Reject(()=>MapPolicy.Validate([maps[0],maps[0]]),"Duplicate map IDs rejected.");
const string sid="76561198000000000";
Check(AccessPolicy.ValidId(sid),"Valid SteamID accepted.");
Check(!AccessPolicy.ValidId("76561198000000000;quit"),"Command injection rejected in SteamID.");
Check(!AccessPolicy.ValidId("00000000000000000"),"Invalid Steam account rejected.");
Check(AccessPolicy.Parse("# comment\n"+sid+"\n"+sid+"\n").Count==1,"List deduplicates exact SteamID.");
Reject(()=>AccessPolicy.Parse("76561198000000000 name"),"Malformed whitelist cannot silently replace file.");
Check(!AccessPolicy.Allows(new(),false,true),"Original whitelist has no implicit admin bypass.");
Check(AccessPolicy.Allows(new(){AdminBypass=true},false,true),"Explicit admin bypass works.");
Check(!AccessPolicy.Allows(new(),false,false),"Non-whitelisted tester denied.");
Check(AccessPolicy.Allows(new(),true,false),"Whitelisted tester admitted.");
Check(!AccessPolicy.Allows(new(){Mode=2},true,false),"Blacklist member denied.");
Check(AccessPolicy.Allows(new(){Mode=2},false,false),"Blacklist nonmember admitted.");
Check(!AccessPolicy.Allows(new(){AdminBypass=false},false,true),"Explicitly disabled bypass respected.");
Check(MapPolicy.MeasuredLimits(10,10,2,0)==(6,18,2),"Two bombsites require six and reserve two slots.");
Check(MapPolicy.MeasuredLimits(10,10,1,0)==(1,18,2),"One bombsite allows one through reserved capacity.");
Check(MapPolicy.MeasuredLimits(10,10,0,2)==(6,18,2),"Hostage maps require six.");
Check(MapPolicy.MeasuredLimits(6,10,2,0)==(6,10,2),"Smaller team determines balanced capacity.");
Check(MapPolicy.MeasuredLimits(10,10,1,0,8)==(1,8,2),"Deliberately lower maximum is retained.");
Check(MapPolicy.MeasuredLimits(1,1,1,0)==(1,2,0),"A genuine 1v1 map cannot reserve a nonexistent slot.");
Reject(()=>MapPolicy.MeasuredLimits(0,10,2,0),"Missing spawns are not a successful zero measurement.");
Reject(()=>MapPolicy.MeasuredLimits(3,3,2,0),"Two-site minimum cannot exceed reserved spawn capacity.");
var limitsMaps=new List<MapEntry>{new(){Id="11",Name="two",MinPlayers=6,MaxPlayers=18},new(){Id="12",Name="one",MinPlayers=1,MaxPlayers=8},new(){Id="13",Name="hostage",MinPlayers=6,MaxPlayers=18}};
Check(MapPolicy.Eligible(limitsMaps,"none","",5,[],0).Select(m=>m.Id).SequenceEqual(["12"]),"Five players see only suitable one-site map.");
Check(MapPolicy.Eligible(limitsMaps,"none","",9,[],0).Select(m=>m.Id).SequenceEqual(["11","13"]),"Too many players hide smaller map.");
Check(MapPolicy.Eligible(limitsMaps,"none","",19,[],0).Count==0,"Overcapacity maps excluded from nomination/vote.");
Check(!MapPolicy.CanVote(1,false)&&MapPolicy.CanVote(2,false)&&MapPolicy.CanVote(1,true),"Spectator voting restriction preserved.");
var rules=new MapSettings();
Check(rules.MapsToShow==10&&rules.VoteSeconds==60&&rules.ChangeDelaySeconds==3&&rules.VerifySeconds==8&&rules.MaxAttempts==3,"Live vote/transition defaults retained.");
Check(!MapPolicy.RtvAllowed(rules,true,5,5)&&MapPolicy.RtvAllowed(rules,false,0,1),"Warmup block and minimum rules preserved.");
Check(!MapPolicy.RtvAllowed(rules with{RtvMinRounds=3},false,2,5),"Minimum rounds respected.");
Check(MapPolicy.NearMatchEnd(20,11,24,0,2)&&!MapPolicy.NearMatchEnd(8,5,24,0,2),"End vote before likely winning round.");
Check(!MapPolicy.Confirmed(maps[1],"custom_map",""),"Workshop transition must not use filename as false success.");
var green=MapPolicy.VoteLabel(new(){Name="Grün <b>",MinPlayers=6,MaxPlayers=18},true);
Check(green.Contains("#55DD77")&&green.Contains("nominiert")&&green.Contains("6–18 Spieler")&&green.Contains("Grün")&&!green.Contains("<b>"),"Nominated map green, safe Unicode name and capacity label.");
Check(!MapPolicy.VoteLabel(maps[0],false).Contains("<font"),"Unnominated map stays neutral.");
var measured=new MapEntry{Id="100",Name="old",Enabled=false,TSpawns=10,CtSpawns=10,BombSites=2,Hostages=0,MeasuredAt=DateTimeOffset.UtcNow,WorkshopUpdated=10,MaxPlayers=18,MinPlayers=6,MeasurementVersion=2};
Check(MapPolicy.Measured(measured)&&!MapPolicy.Measured(measured with{ProbeError="failed"}),"Failed measurement never passes gate.");
var proposal=MapPolicy.CaptureMeasurement(measured with{MinPlayers=4,MaxPlayers=30},10,10,2,0);
Check(proposal.MinPlayers==4&&proposal.MaxPlayers==30&&proposal.LimitProposal!.MinPlayers==6&&proposal.LimitProposal.MaxPlayers==18,"Measurement stages limits without adopting restrictions.");
Check(!MapPolicy.LimitsApproved(proposal)&&new MapSettings().MeasurementOnly,"Unapproved limits and first install cannot enter ordinary voting.");
var accepted=MapPolicy.ApproveLimits(proposal,proposal.LimitProposal!.Signature);
Check(MapPolicy.LimitsApproved(accepted)&&accepted.MinPlayers==6&&accepted.MaxPlayers==18&&!accepted.Enabled,"Approval applies displayed limits while preserving manual disable.");
Check(MapPolicy.LimitsApproved(MapPolicy.CaptureMeasurement(accepted,10,10,2,0)),"Repeated unchanged measurement retains approval.");
var changed=MapPolicy.CaptureMeasurement(accepted,8,10,2,0);
Check(!MapPolicy.LimitsApproved(changed)&&changed.MaxPlayers==18&&changed.LimitProposal!.MaxPlayers==14,"Changed spawn capacity stages a new proposal without overwriting approved limits.");
Reject(()=>MapPolicy.ApproveLimits(changed,proposal.LimitProposal.Signature),"Stale review cannot approve different measurements.");
Reject(()=>MapPolicy.ApproveLimits(proposal with{ProbeError="failed"},proposal.LimitProposal.Signature),"Failed remeasurement cannot approve stale proposal.");
Check(!MapPolicy.LimitsApproved(MapPolicy.CaptureMeasurement(accepted with{WorkshopUpdated=11},10,10,2,0)),"New Workshop revision requires renewed review.");
var merged=WorkshopDetails.Merge([measured,new(){Id="200",Name="removed",MeasuredAt=measured.MeasuredAt}], [new("100","new",true,10,10),new("300","added",true,20,20)]);
Check(!merged.Single(m=>m.Id=="100").Enabled&&MapPolicy.Measured(merged.Single(m=>m.Id=="100")),"Pool refresh preserves manual disable and valid measurements.");
Check(!merged.Single(m=>m.Id=="200").InPool&&merged.Single(m=>m.Id=="200").MeasuredAt==measured.MeasuredAt,"Removed pool member retains history but is excluded.");
Check(!MapPolicy.Measured(merged.Single(m=>m.Id=="300")),"New Workshop maps require empty-server probe.");
Check(!MapPolicy.Measured(WorkshopDetails.Merge([measured],[new("100","updated",true,30,11)]).Single()),"Workshop update invalidates measurement for new probe.");
Check(WorkshopDetails.Merge([measured with{Removed=true}],[new("100","restored",true,10,10)]).Single().Removed,"Rescan cannot remove operator tombstone.");
string Collection(string id,params (string Id,int Type)[] children)=>System.Text.Json.JsonSerializer.Serialize(new {response=new {collectiondetails=new[]{new {publishedfileid=id,result=1,children=children.Select(c=>new {publishedfileid=c.Id,filetype=c.Type})}}}});
int requests=0;
var members=await WorkshopCollections.ResolveMembersAsync("1",(id,_)=>{requests++;return Task.FromResult(id=="1"?Collection("1",("2",2),("100",0)):Collection("2",("1",2),("200",0)));},CancellationToken.None);
Check(requests==2&&members.SetEquals(["100","200"]),"Nested cyclic collections resolve once without leaking collection IDs.");
Reject(()=>WorkshopCollections.ParseResponse(Collection("2"),"1"),"Mismatched collection response rejected.");
Check(WorkshopCollections.ParseStartupArguments(["game","+sv_setsteamaccount","not-exported","+host_workshop_collection","3500873770"])=="3500873770","Only collection ID parsed from startup.");
MemoryStream VpkFixture(string extension)
{
    using var tree=new MemoryStream();using(var w=new BinaryWriter(tree,System.Text.Encoding.UTF8,true))
    {
        void Token(string value){w.Write(System.Text.Encoding.UTF8.GetBytes(value));w.Write((byte)0);}
        Token(extension);Token(extension is "vmap_c" or "vpk"?"maps":"sounds");Token("test");w.Write((uint)0);w.Write((ushort)0);w.Write((ushort)0x7fff);w.Write((uint)0);w.Write((uint)0);w.Write((ushort)0xffff);Token("");Token("");Token("");
    }
    var result=new MemoryStream();using(var w=new BinaryWriter(result,System.Text.Encoding.UTF8,true)){w.Write(0x55aa1234u);w.Write(2u);w.Write((uint)tree.Length);w.Write(new byte[16]);w.Write(tree.ToArray());}result.Position=0;return result;
}
using(var mapVpk=VpkFixture("vmap_c"))Check(VpkMaps.Read(mapVpk).SetEquals(["test"]),"VPK map directory recognized.");
using(var assetVpk=VpkFixture("vsnd_c"))Check(VpkMaps.Read(assetVpk).Count==0,"Sound VPK cannot become a playable map.");
using(var nestedVpk=VpkFixture("vpk"))Check(VpkMaps.Read(nestedVpk).SetEquals(["test"]),"Workshop wrapper with maps/name.vpk is playable.");
Check(MapPolicy.BombSiteCount(2,1,2)==2,"Engine goal positions distinguish A/B even when trigger designations agree.");
Check(MapPolicy.BombSiteCount(3,1,1)==1,"Multiple volumes for one engine goal remain one site.");
Reject(()=>MapPolicy.BombSiteCount(2,1,null),"Ambiguous multiple bomb volumes cannot silently become one site.");
Check(LPLK.Common.AdminActionPolicy.Allowed("ban", p=>p=="admin.ban"),"Explicit ban permission accepted.");
Check(!LPLK.Common.AdminActionPolicy.Allowed("kick", p=>p=="admin.ban"),"Ban-only grant cannot kick.");
Check(LPLK.Common.AdminActionPolicy.Allowed("freeze", p=>p=="lplk.admin"),"LPLK administration accepts moderation.");
Check(!LPLK.Common.AdminActionPolicy.Allowed("server_command",p=>p=="lplk.admin"),"RCON requires its own grant.");
Check(!LPLK.Common.AdminActionPolicy.Allowed("unknown",p=>true),"Unknown backend action rejected.");
Check(!LPLK.Common.AdminActionPolicy.CanTarget(1,2,10,100),"Admin cannot target founder.");
Check(!LPLK.Common.AdminActionPolicy.CanTarget(1,2,100,100),"Equal immunity protected.");
Check(LPLK.Common.AdminActionPolicy.CanTarget(1,2,100,10),"Founder can target lower rank.");
Check(LPLK.Common.AdminActionPolicy.CanTarget(1,1,10,10),"Self-management accepted.");
Check(LPLK.Common.AdminActionPolicy.CanTarget(0,2,0,100),"Server console remains authoritative.");
Check(!LPLK.Common.AdminActionPolicy.SteamId("76561197960265728;quit"),"Command-like SteamID rejected.");
Check(LPLK.Common.AdminActionPolicy.Minutes("0")==0,"Permanent sanction represented explicitly.");
Console.WriteLine($"LPLK addon policy regressions: PASS ({checks} checks). Gameplay requires server/client verification.");

